package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

type User struct {
	ID        string `json:"id"`
	Username  string `json:"username"`
	Email     string `json:"email"`
	Role      string `json:"role"`
	IsAdmin   bool   `json:"is_admin"`
	Balance   int    `json:"balance"`
	Verified  bool   `json:"verified"`
	RateLimit int    `json:"rate_limit"`
}

type UpdateMessage struct {
	Action string          `json:"action"`
	Data   json.RawMessage `json:"data"`
}

var (
	users    = make(map[string]*User)
	usersMu  sync.RWMutex
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
)

func init() {
	users["user-001"] = &User{
		ID: "user-001", Username: "alice", Email: "alice@example.com",
		Role: "member", IsAdmin: false, Balance: 100, Verified: true, RateLimit: 60,
	}
	users["user-002"] = &User{
		ID: "user-002", Username: "bob", Email: "bob@example.com",
		Role: "member", IsAdmin: false, Balance: 50, Verified: false, RateLimit: 60,
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// Authenticate from first message
	_, authMsg, err := conn.ReadMessage()
	if err != nil {
		return
	}
	var authData struct {
		UserID string `json:"user_id"`
	}
	if err := json.Unmarshal(authMsg, &authData); err != nil {
		return
	}

	usersMu.RLock()
	user, exists := users[authData.UserID]
	usersMu.RUnlock()
	if !exists {
		conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"unauthorized"}`))
		return
	}

	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var update UpdateMessage
		if err := json.Unmarshal(msg, &update); err != nil {
			continue
		}

		switch update.Action {
		case "update_profile":
			// Mass assignment vulnerability: unmarshal directly into user struct
			// allowing clients to set Role, IsAdmin, Balance, etc.
			usersMu.Lock()
			json.Unmarshal(update.Data, user)
			usersMu.Unlock()

			respBytes, _ := json.Marshal(user)
			conn.WriteMessage(websocket.TextMessage, respBytes)

		case "get_profile":
			usersMu.RLock()
			respBytes, _ := json.Marshal(user)
			usersMu.RUnlock()
			conn.WriteMessage(websocket.TextMessage, respBytes)
		}
	}
}

func serveIndex(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html")
	w.Write([]byte(`<!DOCTYPE html>
<html>
<head>
  <script src="/static/ws-client.js"
    integrity="sha384-oqVuAfXRKap7fdgcCY5uykM6+R9GqQ8K/uxy9rx7HNQlGYl1kPzQho1wx4JwY8wC"
    crossorigin="anonymous"></script>
</head>
<body><div id="app"></div></body>
</html>`))
}

func main() {
	http.HandleFunc("/", serveIndex)
	http.HandleFunc("/ws", handleWebSocket)
	http.Handle("/static/", http.StripPrefix("/static/", http.FileServer(http.Dir("./static"))))
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
